{
  "probability": 0.01,
  "range_low": 0.01,
  "range_high": 0.04,
  "summary": [
    "Late-February 2026 polls place CDU and Greens ahead of AfD in Baden-Württemberg, making AfD unlikely to top the Landtag.",
    "Historical base-rate indicates AfD has never led BW; Greens led in 2021 and polling keeps AfD well behind.",
    "Polls show AfD around 18–21%, with CDU around 27–29% and Greens around 20–27%, reducing odds of a majority for AfD.",
    "Bayesian integration with these factors yields a very low probability (~1%) of AfD winning the most seats."
  ],
  "confidence": "high",
  "narrative": "Current polling and historical patterns strongly constrain AfD from winning the most seats in Baden-Württemberg. The posterior probability of about 1% reflects the base-rate and the plurality of polls showing CDU/Greens ahead, with only limited upside risk from turnout or late campaign shifts.",
  "justification": {
    "anchor": {
      "probability": 0.05,
      "basis": "Base-rate reference class: BW elections under proportional representation; historically the largest party has been CDU or Greens. The anchor probability (~5%) provides a plausible starting point before applying the late-February 2026 updates."
    },
    "factor_updates": [
      {
        "factor": "CDU leads in polls relative to AfD",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Polls place CDU around 27–29% and AfD around 18–21%, meaning AfD would need to overtake CDU to top the Landtag, which current data do not support."
      },
      {
        "factor": "Greens competitive but not majority; AfD trailing top two",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Greens poll ~20–27% alongside CDU ~27–29%, which keeps AfD from becoming the largest party under proportional representation."
      },
      {
        "factor": "Historical base-rate: AfD has never been largest in BW",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "2021 results showed Greens atop the chamber and AfD well behind, establishing a base-rate that makes a top-seat outcome for AfD unlikely without a substantial shift."
      },
      {
        "factor": "Forecast consensus across multiple polls",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Multiple credible polls consistently place CDU and Greens ahead of AfD, reducing the probability of AfD winning the most seats."
      }
    ],
    "synthesis_rationale": "Starting from a modest base-rate anchor around 5%, the ensemble of factors yields consistent downward updates with relatively small calibration adjustments for potential correlated information among polls. The strong, repeated polling signal combined with historical patterns supports a very low posterior of 1%, acknowledging some residual uncertainty from turnout effects and late-stage campaign dynamics."
  }
}

